(ROOT/'notebooks').mkdir(exist_ok=True)
(ROOT/'notebooks'/'experiment_001.ipynb').write_text(json.dumps(dict(cells=cells,metadata=dict(kernelspec=dict(display_name='Python 3',language='python',name='python3')),nbformat=4,nbformat_minor=5),indent=2),encoding='utf-8')
